		if (paths == null || index >= paths.length)
		{
			promise.error("");
			return;
		}

		loadFromFileStream(paths[index]).onProgress(promise.progress).onComplete(function(buffer)
		{
			if (buffer != null)
			{
				promise.complete(buffer);
			}
			else
			{
				__loadFromFilesStream(paths, promise, index + 1);
			}
		}).onError(function(_)
		{
				__loadFromFilesStream(paths, promise, index + 1);
		});
	}

