package lime.system;

import lime.app.Application;
import lime.app.Event;
#if sys
#if haxe4
import sys.thread.Deque;
import sys.thread.Thread;
#elseif cpp
import cpp.vm.Deque;
import cpp.vm.Thread;
#elseif neko
import neko.vm.Deque;
import neko.vm.Thread;
#end
#end
/**
	A `BackgroundWorker` allows the execution of a function on a background thread, 
	avoiding the blocking of the main thread. This is particularly useful for long-running 
	operations like file I/O, network requests, or computationally intensive tasks.

	### Notes:
	- **Thread Support:** Only system targets (such as C++, Neko) support threading. 
	- **Events:** The class uses the `Event` class to dispatch completion, error, 
	  and progress notifications.

	@see `ThreadPool` for more advanced threading capabilities, including thread 
	safety, HTML5 threads, and more robust handling of tasks.
**/
#if !lime_debug
@:fileXml('tags="haxe,release"')
@:noDebug
#end
class BackgroundWorker
{
	private static var MESSAGE_COMPLETE = "__COMPLETE__";
	private static var MESSAGE_ERROR = "__ERROR__";

	/**
		Indicates whether the worker has been canceled.
	**/
	public var canceled(default, null):Bool;

	/**
		Indicates whether the worker has completed its task.
	**/
	public var completed(default, null):Bool;

	/**
		Dispatched when the worker is about to perform its task.
		The function to execute should be added as a listener to this event.
	**/
	public var doWork = new Event<Dynamic->Void>();

	/**
		Dispatched when the worker has successfully completed its task.
	**/
	public var onComplete = new Event<Dynamic->Void>();

	/**
		Dispatched if an error occurs during the execution of the worker's task.
	**/
	public var onError = new Event<Dynamic->Void>();

	/**
		Dispatched periodically during the worker's task to provide progress updates.
	**/
	public var onProgress = new Event<Dynamic->Void>();

	@:noCompletion private var __runMessage:Dynamic;
	#if (cpp || neko || (haxe4 && hl))
	@:noCompletion private var __messageQueue:Deque<Dynamic>;
	@:noCompletion private var __workerThread:Thread;
	#end

	/**
		Creates a new `BackgroundWorker` instance.
	**/
	public function new() {}

	/**
		Cancels the worker's task if it is still running. This won't stop the thread 
		immediately.
	**/
	public function cancel():Void
	{
		canceled = true;

		#if (cpp || neko || (haxe4 && hl))
		__workerThread = null;
		#end
	}

	/**
		Starts the worker's task, optionally passing a message to the task.
		@param message An optional message to pass to the worker's task.
	**/
	public function run(message:Dynamic = null):Void
	{
		canceled = false;
		completed = false;
		__runMessage = message;

		#if (cpp || neko || (haxe4 && hl))
		__messageQueue = new Deque<Dynamic>();
		__workerThread = Thread.create(__doWork);

		// TODO: Better way to do this

		if (Application.current != null)
		{
			Application.current.onUpdate.add(__update);
		}
		#else
		__doWork();
		#end
	}

	/**
		Sends a completion message, indicating that the worker has finished its task.
		@param message An optional message to pass to the `onComplete` event.
	**/
	public function sendComplete(message:Dynamic = null):Void
	{
		completed = true;

		#if (cpp || neko || (haxe4 && hl))
		__messageQueue.add(MESSAGE_COMPLETE);
		__messageQueue.add(message);
		#else
		if (!canceled)
		{
			canceled = true;
			onComplete.dispatch(message);
		}
		#end
	}

	/**
		Sends an error message, indicating that an error occurred during the worker's task.
		@param message An optional message to pass to the `onError` event.
	**/
	public function sendError(message:Dynamic = null):Void
	{
		#if (cpp || neko || (haxe4 && hl))
		__messageQueue.add(MESSAGE_ERROR);
		__messageQueue.add(message);
		#else
		if (!canceled)
		{
			canceled = true;
			onError.dispatch(message);
		}
		#end
	}

	/**
		Sends a progress update message.
		@param message An optional message to pass to the `onProgress` event.
	**/
	public function sendProgress(message:Dynamic = null):Void
	{
		#if (cpp || neko || (haxe4 && hl))
		__messageQueue.add(message);
		#else
		if (!canceled)
		{
			onProgress.dispatch(message);
		}
		#end
	}

	@:noCompletion private function __doWork():Void
	{
		doWork.dispatch(__runMessage);

		// #if (cpp || neko)
		//
		// __messageQueue.add (MESSAGE_COMPLETE);
		//
		// #else
		//
		// if (!canceled) {
		//
		// canceled = true;
		// onComplete.dispatch (null);
		//
		// }
		//
		// #end
	}

	@:noCompletion private function __update(deltaTime:Int):Void
	{
		#if (cpp || neko || (haxe4 && hl))
		var message = __messageQueue.pop(false);

		if (message != null)
		{
			if (message == MESSAGE_ERROR)
			{
				Application.current.onUpdate.remove(__update);

				if (!canceled)
				{
					canceled = true;
					onError.dispatch(__messageQueue.pop(false));
				}
			}
			else if (message == MESSAGE_COMPLETE)
			{
				Application.current.onUpdate.remove(__update);

				if (!canceled)
				{
					canceled = true;
					onComplete.dispatch(__messageQueue.pop(false));
				}
			}
			else
			{
				if (!canceled)
				{
					onProgress.dispatch(message);
				}
			}
		}
		#end
	}
}

files.lime/system/CFFI.hx:
package lime.system;

#if (!lime_doc_gen || lime_cffi)
import haxe.io.Path;
import lime._internal.macros.CFFIMacro;
#if (sys && !macro)
import sys.io.Process;
#end

#if !lime_debug
@:fileXml('tags="haxe,release"')
@:noDebug
#end
class CFFI
{
	@:noCompletion private static var __moduleNames:Map<String, String> = null;
	#if neko
	private static var __loadedNekoAPI:Bool;
	#elseif nodejs
	private static var __nodeNDLLModule:Dynamic;
	#end
	public static var available:Bool;
	public static var enabled:Bool;

	private static function __init__():Void
	{
		#if lime_cffi
		available = true;
		enabled = #if disable_cffi false; #else true; #end
		#else
		available = false;
		enabled = false;
		#end
	}

	#if macro
	public static function build(defaultLibrary:String = "lime")
	{
		return CFFIMacro.build(defaultLibrary);
	}
	#end

	/**
	 * Tries to load a native CFFI primitive on compatible platforms
	 * @param	library	The name of the native library (such as "lime")
	 * @param	method	The exported primitive method name
	 * @param	args	The number of arguments
	 * @param	lazy	Whether to load the symbol immediately, or to allow lazy loading
	 * @return	The loaded method
	 */
	public static function load(library:String, method:String, args:Int = 0, lazy:Bool = false):Dynamic
	{
		#if (disable_cffi || macro || hl)
		var enabled = false;
		#end

		#if optional_cffi
		if (library != "lime" || method != "neko_init")
		{
			lazy = true;
		}
		#end

		if (!enabled)
		{
			return Reflect.makeVarArgs(function(__) return {});
		}

		var result:Dynamic = null;

		#if (!disable_cffi && !macro)
		#if (sys && !html5)
		if (__moduleNames == null) __moduleNames = new Map<String, String>();

		if (lazy)
		{
			__moduleNames.set(library, library);

			try
			{
				#if neko
				result = neko.Lib.loadLazy(library, method, args);
				#elseif java
				result = __loadJava(library, method, args);
				#elseif cpp
				result = cpp.Lib.loadLazy(library, method, args);
				#end
			}
			catch (e:Dynamic) {}
		}
		else
		{
			#if (cpp && (iphone || webassembly || android || static_link || tvos))
			return cpp.Lib.load(library, method, args);
			#end

			if (__moduleNames.exists(library))
			{
				#if cpp
				return cpp.Lib.load(__moduleNames.get(library), method, args);
				#elseif neko
				#if neko_cffi_trace
				var result:Dynamic = neko.Lib.load(__moduleNames.get(library), method, args);
				if (result == null) return null;

				return Reflect.makeVarArgs(function(args)
				{
					trace("Called " + library + "@" + method);
					return Reflect.callMethod(result, result, args);
				});
				#else
				return neko.Lib.load(__moduleNames.get(library), method, args);
				#end
				#elseif nodejs
				return untyped __nodeNDLLModule.load_lib(__moduleNames.get(library), method, args);
				#elseif java
				result = __loadJava(__moduleNames.get(library), method, args);
				#elseif cs
				return untyped CSFunctionLoader.load(__moduleNames.get(library), method, args);
				#else
				return null;
				#end
			}

			#if waxe
			if (library == "lime")
			{
				flash.Lib.load("waxe", "wx_boot", 1);
			}
			#elseif nodejs
			if (__nodeNDLLModule == null)
			{
				__nodeNDLLModule = untyped require('ndll');
			}
			#end

			__moduleNames.set(library, library);

			var programPath:String = ".";
			#if sys
			programPath = Path.directory(Sys.programPath());
			#end

			result = __tryLoad(programPath + "/" + library, library, method, args);

			if (result == null)
			{
				result = __tryLoad(programPath + "\\" + library, library, method, args);
			}

			if (result == null)
			{
				result = __tryLoad(library, library, method, args);
			}

			if (result == null)
			{
				var ndllFolder = __findNDLLFolder();

				if (ndllFolder != "")
				{
					result = __tryLoad(ndllFolder + __sysName() + "/" + library, library, method, args);

					if (result == null)
					{
						result = __tryLoad(ndllFolder + __sysName() + "64/" + library, library, method, args);
					}

					if (result == null)
					{
						result = __tryLoad(ndllFolder + __sysName() + "Arm64/" + library, library, method, args);
					}
				}
			}

			__loaderTrace("Result : " + result);
		}

		#if neko
		if (library == "lime" && method != "neko_init")
		{
			__loadNekoAPI(lazy);
		}
		#end
		#end
		#else
		result = function(_, _, _, _, _, _)
		{
			return {};
		};
		#end

		return result;
	}

	public static macro function loadPrime(library:String, method:String, signature:String, lazy:Bool = false):Dynamic
	{
		#if (!display && !macro && cpp && !disable_cffi)
		return cpp.Prime.load(library, method, signature, lazy);
		#else
		var args = signature.length - 1;

		if (args > 5)
		{
			args = -1;
		}

		return {call: CFFI.load(library, method, args, lazy)};
		#end
	}

	@:dox(hide) #if !hl inline #end public static function stringValue(#if hl value:hl.Bytes #else value:String #end):String
	{
		#if hl
		return value != null ? @:privateAccess String.fromUTF8(value) : null;
		#else
		return value;
		#end
	}

	private static function __findNDLLFolder():String
	{
		#if (sys && !macro && !html5)
		var process = new Process("haxelib", ["path", "lime"]);

		try
		{
			while (true)
			{
				var line = StringTools.trim(process.stdout.readLine());

				if (StringTools.startsWith(line, "-L "))
				{
					process.close();
					return Path.addTrailingSlash(line.substr(3));
				}
			}
		}
		catch (e:Dynamic) {}

		process.close();
		#end

		return "";
	}

	private static function __loaderTrace(message:String)
	{
		#if (sys && !html5)
		// #if (haxe_ver < 3.4)
		// var get_env = cpp.Lib.load ("std", "get_env", 1);
		// var debug = (get_env ("OPENFL_LOAD_DEBUG") != null);
		// #else
		var debug = (Sys.getEnv("OPENFL_LOAD_DEBUG") != null);
		// #end

		if (debug)
		{
			Sys.println(message);
		}
		#end
	}

	#if java
	private static var __loadedLibraries = new Map<String, Bool>();

	private static function __loadJava(library:String, method:String, args:Int = 0)
	{
		if (!__loadedLibraries.exists(library))
		{
			var extension = #if android ".so" #else ".ndll" #end;
			var path = Sys.getCwd() + "/" + library + extension;

			java.lang.System.load(path);

			__loadedLibraries.set(library, true);

			trace("load library: " + library);
		}

		return null;
	}
	#end

	#if neko
	private static function __loadNekoAPI(lazy:Bool):Void
	{
		if (!__loadedNekoAPI)
		{
			var init:Dynamic = null;
			var error:Dynamic = null;
			try
			{
				init = load("lime", "neko_init", 5);
			}
			catch (e:Dynamic)
			{
				error = e;
			}

			if (init != null)
			{
