			dataPosition += 4;

			var height:Int = bytes.getInt32(dataPosition);
			dataPosition += 4;

			var x:Int = bytes.getInt32(dataPosition);
			dataPosition += 4;

			var y:Int = bytes.getInt32(dataPosition);
			dataPosition += 4;

			// Check if width and height are valid before proceeding
			if (width <= 0 || height <= 0)
			{
				return null;
			}

