			var count = bytes.getInt32(bytesPosition);
			bytesPosition += 4;

			var bufferWidth = 128;
			var bufferHeight = 128;
			var offsetX = 0;
			var offsetY = 0;
			var maxRows = 0;

			var width:Int;
			var height:Int;
			var i = 0;

			while (i < count)
			{
				bytesPosition += 4;
				width = bytes.getInt32(bytesPosition);
				bytesPosition += 4;
				height = bytes.getInt32(bytesPosition);
				bytesPosition += 4;

				bytesPosition += (4 * 2) + width * height;

				if (offsetX + width > bufferWidth)
				{
					offsetY += maxRows + 1;
					offsetX = 0;
					maxRows = 0;
				}

				if (offsetY + height > bufferHeight)
				{
					if (bufferWidth < bufferHeight)
					{
						bufferWidth *= 2;
					}
					else
					{
						bufferHeight *= 2;
					}

					offsetX = 0;
					offsetY = 0;
					maxRows = 0;

					// TODO: make this better

					bytesPosition = 4;
					i = 0;
					continue;
				}

				offsetX += width + 1;

				if (height > maxRows)
				{
					maxRows = height;
				}

				i++;
			}

			var map = new Map<Int, Image>();
			var buffer = new ImageBuffer(null, bufferWidth, bufferHeight, 8);
			var dataPosition = 0;
			var data = Bytes.alloc(bufferWidth * bufferHeight);

			bytesPosition = 4;
			offsetX = 0;
			offsetY = 0;
			maxRows = 0;

			var index:Int;
			var x:Int;
			var y:Int;
			var image:Image;

			for (i in 0...count)
			{
				index = bytes.getInt32(bytesPosition);
				bytesPosition += 4;
				width = bytes.getInt32(bytesPosition);
				bytesPosition += 4;
				height = bytes.getInt32(bytesPosition);
				bytesPosition += 4;
				x = bytes.getInt32(bytesPosition);
				bytesPosition += 4;
				y = bytes.getInt32(bytesPosition);
				bytesPosition += 4;

				if (offsetX + width > bufferWidth)
				{
					offsetY += maxRows + 1;
					offsetX = 0;
					maxRows = 0;
				}

				for (i in 0...height)
				{
					dataPosition = ((i + offsetY) * bufferWidth) + offsetX;
					data.blit(dataPosition, bytes, bytesPosition, width);
					bytesPosition += width;
				}

				image = new Image(buffer, offsetX, offsetY, width, height);
				image.x = x;
				image.y = y;

				map.set(index, image);

				offsetX += width + 1;

				if (height > maxRows)
