			10, /*10.1,*/
			10.2,
			10.3,
			11,
			11.1,
			11.2,
			11.3,
			11.4,
			11.5,
			11.6,
			11.7,
			11.8,
			12,
			13,
			14
		];

		var flashVersion = 9;

		if (project.app.swfVersion > 14)
		{
			flashVersion += Std.int((swfVersions.length - 1) + (project.app.swfVersion - 14));
