		urlRequest.url = uri;
		urlRequest.contentType = parent.contentType;

		// urlRequest.userAgent = parent.userAgent;
		// urlRequest.followRedirects = parent.followRedirects;

		urlRequest.method = switch (parent.method)
		{
			case POST: URLRequestMethod.POST;
