	public function getUniform(program:GLProgram, location:GLUniformLocation):Dynamic
	{
		var info = getActiveUniform(program, location);

		var bools = 0;
		var ints = 0;
		var floats = 0;

		switch (info.type)
		{
			case GL.BOOL:
				bools = 1;
			case GL.INT:
				ints = 1;
			case GL.FLOAT:
				floats = 1;
			case GL.FLOAT_VEC2:
				floats = 2;
			case GL.INT_VEC2:
				ints = 2;
			case GL.BOOL_VEC2:
				bools = 2;
			case GL.FLOAT_VEC3:
				floats = 3;
			case GL.INT_VEC3:
				ints = 3;
			case GL.BOOL_VEC3:
				bools = 3;
			case GL.FLOAT_VEC4:
				floats = 4;
			case GL.INT_VEC4:
				ints = 4;
			case GL.BOOL_VEC4:
				bools = 4;
			case GL.FLOAT_MAT2:
				floats = 4;
			case GL.FLOAT_MAT2x3:
				floats = 12;
			case GL.FLOAT_MAT2x4:
				floats = 16;
			case GL.FLOAT_MAT3:
				floats = 9;
			case GL.FLOAT_MAT3x2:
				floats = 18;
			case GL.FLOAT_MAT3x4:
				floats = 36;
			case GL.FLOAT_MAT4:
				floats = 16;
			case GL.FLOAT_MAT4x2:
				floats = 32;
			case GL.FLOAT_MAT4x3:
				floats = 48;
			case GL.SAMPLER_2D, GL.SAMPLER_3D, GL.SAMPLER_CUBE, GL.SAMPLER_2D_SHADOW:
				ints = 1;
			default:
				return null;
		}

		if (bools == 1)
		{
			return getUniformi(program, location) != 0;
		}
		else if (ints == 1)
		{
			return getUniformi(program, location);
		}
		else if (floats == 1)
		{
			return getUniformf(program, location);
		}
		else if (bools > 0)
		{
			var params = Bytes.alloc(bools);
			getUniformiv(program, location, params);

			var data = new Array<Bool>();

			for (i in 0...bools)
			{
				data[i] = params.get(i) != 0;
			}

			return data;
		}
		else if (ints > 0)
		{
			var params = new Int32Array(ints);
			getUniformiv(program, location, params);
			return params;
		}
		else if (floats > 0)
		{
			var params = new Float32Array(floats);
			getUniformfv(program, location, params);
			return params;
		}
		else
		{
			return null;
		}
	}

