				useHardware = true;

				contextAttributes.hardware = true;
				#if lime_opengl
				context.gl = gl;
				#end
				context.gles2 = gl;
				context.webgl = gl;
				context.type = gl.type;

				context.version = Std.string(gl.version);
				if (gl.type == OPENGLES && gl.version >= 3)
				{
					context.gles3 = gl;
					context.webgl2 = gl;
				}
				if (GL.context == null)
				{
					GL.context = gl;
				}
