	private static #if cpp inline #end function __boxBlurH(imgA:UInt8Array, imgB:UInt8Array, w:Int, h:Int, r:Int, off:Int):Void
	{
		var iarr = 1 / (r + r + 1);
		var ti:Int;
		var li:Int;
		var ri:Int;
		var fv:Int;
		var lv:Int;
		var val:Int;

		for (i in 0...h)
		{
			ti = i * w;
			li = ti;
			ri = ti + r;

			fv = imgA[ti * 4 + off];
			lv = imgA[(ti + w - 1) * 4 + off];
			val = (r + 1) * fv;

			for (j in 0...r)
			{
				val += imgA[(ti + j) * 4 + off];
			}

			for (j in 0...(r + 1))
			{
				val += imgA[ri * 4 + off] - fv;
				imgB[ti * 4 + off] = Math.round(val * iarr);
				ri++;
				ti++;
			}

			for (j in (r + 1)...(w - r))
			{
				val += imgA[ri * 4 + off] - imgA[li * 4 + off];
				imgB[ti * 4 + off] = Math.round(val * iarr);
				ri++;
				li++;
				ti++;
			}

			for (j in (w - r)...w)
			{
				val += lv - imgA[li * 4 + off];
				imgB[ti * 4 + off] = Math.round(val * iarr);
				li++;
				ti++;
			}
		}
	}

	private static inline function __boxBlurT(imgA:UInt8Array, imgB:UInt8Array, w:Int, h:Int, r:Int, off:Int):Void
	{
		var iarr = 1 / (r + r + 1);
		var ws = w * 4;
		var ti:Int;
		var li:Int;
		var ri:Int;
		var fv:Int;
		var lv:Int;
		var val:Int;

		for (i in 0...w)
		{
			ti = i * 4 + off;
			li = ti;
			ri = ti + (r * ws);

			fv = imgA[ti];
			lv = imgA[ti + (ws * (h - 1))];
			val = (r + 1) * fv;

			for (j in 0...r)
			{
				val += imgA[ti + (j * ws)];
			}

			for (j in 0...(r + 1))
			{
				val += imgA[ri] - fv;
				imgB[ti] = Math.round(val * iarr);
				ri += ws;
				ti += ws;
			}

			for (j in (r + 1)...(h - r))
			{
				val += imgA[ri] - imgA[li];
				imgB[ti] = Math.round(val * iarr);
				li += ws;
				ri += ws;
				ti += ws;
			}

			for (j in (h - r)...h)
			{
				val += lv - imgA[li];
				imgB[ti] = Math.round(val * iarr);
				li += ws;
				ti += ws;
			}
		}
	}

	/**
