		}

		return sizes;
	}

	private static inline function __pixelCompare(n1:UInt, n2:UInt):Int
	{
		var tmp1:UInt;
		var tmp2:UInt;

		tmp1 = (n1 >> 24) & 0xFF;
		tmp2 = (n2 >> 24) & 0xFF;

		if (tmp1 != tmp2)
