			return (tmp1 > tmp2 ? 1 : -1);
		}
		else
		{
			tmp1 = (n1 >> 16) & 0xFF;
			tmp2 = (n2 >> 16) & 0xFF;

			if (tmp1 != tmp2)
			{
				return (tmp1 > tmp2 ? 1 : -1);
			}
			else
			{
