			imgB[d + 1] = imgB[s + 1];
			imgB[d + 2] = imgB[s + 2];

			var a = Std.int(imgB[s + 3] * strength);
			imgB[d + 3] = a < 0 ? 0 : (a > 255 ? 255 : a);
		}
