							pb = Std.int(((b * ms) >>> ss) * f);
							px[p] = pr > 255 ? 255 : pr;
							px[p + 1] = pg > 255 ? 255 : pg;
							px[p + 2] = pb > 255 ? 255 : pb;
						}
						else
