package lime._internal.unifill;

abstract Utf16(StringU16)
{
	/**
		Converts the code point `code` to a character as a Utf16 string.
	**/
	public static inline function fromCodePoint(codePoint:Int):Utf16
	{
		if (codePoint <= 0xFFFF)
